<div class="page-header d-flex"><h2><?= lang('dashboard') ?></h2><a class="btn btn-outline-danger ms-auto" href="<?= site_url('reports/low_stock') ?>"><?= lang('low_stock_report') ?>: <?= e($lowStockCount) ?></a></div><div class="row row-deck row-cards"><?php foreach ($stats as $label => $value): ?><div class="col-sm-6 col-lg-3"><div class="card"><div class="card-body"><div class="subheader"><?= e(lang('stat_' . $label)) ?></div><div class="h1 mb-0"><?= $label === 'sales' ? sar($value) : e($value) ?></div></div></div></div><?php endforeach; ?></div><div class="card mt-3"><div class="card-header"><h3 class="card-title"><?= lang('invoices') ?></h3></div><table class="table"><thead><tr><th><?= lang('number') ?></th><th><?= lang('customer') ?></th><th><?= lang('status') ?></th><th><?= lang('total') ?></th></tr></thead><tbody><?php foreach ($recentInvoices as $invoice): ?><tr><td><a href="<?= site_url('invoices/show/'.$invoice['id']) ?>"><?= e($invoice['invoice_number']) ?></a></td><td><?= e($invoice['customer_name']) ?></td><td><?= e(lang($invoice['status'])) ?></td><td><?= sar($invoice['total']) ?></td></tr><?php endforeach; ?></tbody></table></div>
